<style scoped lang="scss" src="./meter.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { has } from "../../util/has";
import { MeterMode, MeterModeValues } from "./meter.constants";
import { CurrencyNotation, CurrencyNotationValues } from "../constants";
import { currencyFormat } from "../../util/currency-format";

/**
 * It is a component to show the progress of a fund with specific number and progress bar
 */
@Component
export default class Meter extends Vue {
  @Prop({ type: Number, default: 0 }) collected;
  @Prop({ type: Number }) collectedToday;
  @Prop({ type: Number }) goal;
  @Prop({
    type: String,
    default: MeterMode.SMALL,
    validator: has(MeterModeValues)
  })
  mode;
  @Prop({
    type: String,
    default: CurrencyNotation.USD,
    validator: has(CurrencyNotationValues)
  })
  currency;

  get dollarFontClass() {
    switch (this.mode) {
      case MeterMode.LARGE:
      case MeterMode.LARGE_MOBILE:
        return "Meter--fontLargeDollar";
      case MeterMode.MEDIUM:
      case MeterMode.MEDIUM_EMPHASIZED:
        return "Meter--fontMediumBlack";
      case MeterMode.SUMMARY:
        return "Meter--fontLargeDollar";
      default:
        return "Meter--fontSmallBlack";
    }
  }

  get collectedFontClass() {
    switch (this.mode) {
      case MeterMode.LARGE:
        return "Meter--fontLargeBlack";
      case MeterMode.LARGE_MOBILE:
        return "Meter--fontLargeMobile";
      case MeterMode.MEDIUM_EMPHASIZED:
        return "Meter--fontMediumEmphasizedBlack";
      case MeterMode.MEDIUM:
        return "Meter--fontMediumBlack";
      case MeterMode.SUMMARY:
        return "Meter--fontLessLargeBlack";
      default:
        return "Meter--fontSmallBlack";
    }
  }

  get goalFontClass() {
    switch (this.mode) {
      case MeterMode.LARGE:
      case MeterMode.LARGE_MOBILE:
        return "Meter--fontLargeGrey";
      case MeterMode.MEDIUM:
        return "Meter--fontMediumGrey";
      case MeterMode.MEDIUM_EMPHASIZED:
        return "Meter--fontMediumEmphasizedGrey";
      case MeterMode.SUMMARY:
        return "Meter--fontLargeGrey";
      default:
        return "Meter--fontSmallGrey";
    }
  }

  get progressBarClass() {
    return {
      Meter__ProgressBackground: true,
      [`Meter--${this.mode}`]: true
    };
  }

  get barBackgroundStyle() {
    return {
      width: `100%`
    };
  }

  get barStyle() {
    const minWidth =
      this.collected === 0 || this.collected === null
        ? 0
        : this.mode === MeterMode.LARGE ||
          this.mode === MeterMode.GOAL ||
          this.mode === MeterMode.LARGE_MOBILE
        ? 16
        : this.mode === MeterMode.SUMMARY
        ? 4
        : 8;

    if ((!this.goal || this.goal == 0) && this.collected === 0) {
      return {
        width: `${0}%`,
        minWidth: `${0}px`
      };
    }

    const barWidth = this.goal
      ? (Math.min(this.collected, this.goal) / this.goal) * 100
      : 100;

    return {
      width: `${barWidth}%`,
      minWidth: `${minWidth}px`
    };
  }

  get collectedString() {
    return currencyFormat(this.collected);
  }

  get collectedTodayString() {
    return currencyFormat(this.collectedToday);
  }

  get goalString() {
    return currencyFormat(this.goal);
  }

  get meterStyle() {
    if (this.mode === MeterMode.GOAL) {
      return {
        alignItems: "center"
      };
    }

    return {};
  }

  get progressStyle() {
    if (this.mode === MeterMode.LARGE_MOBILE) {
      return {
        alignItems: "flex-end"
      };
    }

    return {};
  }

  isNotLarge() {
    return Boolean(this.mode !== MeterMode.LARGE);
  }

  isInGoalMode() {
    return Boolean(this.mode === MeterMode.GOAL);
  }
}
</script>

<template>
  <div class="Meter" :style="meterStyle">
    <div v-if="isInGoalMode()" class="Meter__Goal">
      <div class="Meter__fontGoalGrey">{{ `Your goal is` }}</div>
      <div class="Meter__fontGoalBlack">
        &nbsp;{{ `${this.currency}${goalString}.` }}
      </div>
    </div>
    <div v-else class="Meter__Progress" :style="progressStyle">
      <div :class="dollarFontClass">{{ this.currency }}</div>
      <div :class="collectedFontClass">{{ collectedString }}</div>
      <div v-if="this.goal && this.goal > 0">
        <div v-if="isNotLarge()" :class="goalFontClass">
          &nbsp;{{ `of ${this.currency}${goalString}` }}
        </div>
        <div v-else :class="goalFontClass">
          {{ `of ${this.currency}${goalString}` }}
        </div>
      </div>
    </div>

    <div :class="progressBarClass" :style="barBackgroundStyle">
      <div class="Meter__ProgressBar" :style="barStyle"></div>
    </div>

    <div v-if="isInGoalMode()" class="Meter__Collected">
      <span class="Meter__fontMediumGrey">{{ "You've collected " }}</span>
      <span class="Meter__fontMediumBlack">
        &nbsp;{{ `${this.currency}${collectedString}.` }}
      </span>
    </div>
    <div v-if="isInGoalMode()" class="Meter__Today">
      {{ `${this.currency}${collectedTodayString} today` }}
    </div>
  </div>
</template>
